class ChainableSynthesis {
        constructor() {
            this.f = [];
        }
        map(fn) {
            this.f.push(fn);
            return this;
        }
        forEach(fn) {
            this.f.push(v => {
                fn(v);
                return v;
            });
            return this;
        }
        filter(fn) {
            this.f.push(v => fn(v) ? v : HaltChainable);
            return this;
        }
        reduce(merge, initial) {
            let last = initial;
            this.f.push(v => {
                last = merge(last, v);
                return last;
            });
            return this;
        }
        latch(equals = (a, b) => a === b) {
            let firstCall = true;
            let cache;
            this.f.push(value => {
                const shouldEmit = firstCall || !equals(value, cache);
                firstCall = false;
                cache = value;
                return shouldEmit ? value : HaltChainable;
            });
